use strict; use warnings; use utf8; use IO::Socket::INET; binmode STDOUT, ':encoding(UTF-8)';
sub u{ return (qw(cero uno dos tres cuatro cinco seis siete ocho nueve))[$_[0]]; }
sub c{ my$n=shift; my%e=(10=>'diez',11=>'once',12=>'doce',13=>'trece',14=>'catorce',15=>'quince',16=>'dieciseis',17=>'diecisiete',18=>'dieciocho',19=>'diecinueve',20=>'veinte',21=>'veintiuno',22=>'veintidos',23=>'veintitres',24=>'veinticuatro',25=>'veinticinco',26=>'veintiseis',27=>'veintisiete',28=>'veintiocho',29=>'veintinueve'); my%d=(30=>'treinta',40=>'cuarenta',50=>'cincuenta',60=>'sesenta',70=>'setenta',80=>'ochenta',90=>'noventa'); my%ci=(100=>'cien',200=>'doscientos',300=>'trescientos',400=>'cuatrocientos',500=>'quinientos',600=>'seiscientos',700=>'setecientos',800=>'ochocientos',900=>'novecientos'); return u($n) if $n<10; return $e{$n} if $e{$n}; if($n<100){my$de=int($n/10)*10;my$un=$n%10;return $un?$d{$de}.' y '.u($un):$d{$de};} return $ci{$n} if $ci{$n}; my$ce=int($n/100)*100;my$r=$n%100;return ($ce==100?'ciento':$ci{$ce}).' '.c($r); }
sub num{ my$n=shift; return 'cero' if $n==0; return 'menos '.num(-$n) if $n<0; return c($n) if $n<1000; if($n<1000000){my$m=int($n/1000);my$r=$n%1000;my$p=$m==1?'mil':num($m).' mil';return $r?$p.' '.c($r):$p;} my$m=int($n/1000000);my$r=$n%1000000;my$p=$m==1?'un millon':num($m).' millones';return $r?$p.' '.num($r):$p; }
my $server=IO::Socket::INET->new(LocalPort=>3000,Listen=>5,Reuse=>1) or die $!; print "Servidor en http://localhost:3000/?n=10\n";
while(my $client=$server->accept){ my $req=<$client>; my($n)=$req=~/\?n=([0-9]+)/; $n//=10; my $out=num($n); print $client "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\n\r\n$out"; close $client; }
